344	 * declare which event types they want, so an endpoint only ever receives what
345	 * it subscribed to; the job drains the rows afterwards.
346	 */
347	export function registerWebhookListeners(): Unsubscribe {
348	  const offs: Unsubscribe[] = [
349	    subscribe("webhook.delivery_requested", async (payload) => {
350	      await enqueueForOrg(
351	        payload.orgId,
352	        payload.eventType,
353	        JSON.stringify(payload.payload),
354	      );
355	    }),
356	    subscribe("issue.created", async (payload) => {
357	      await enqueueForOrg(payload.orgId, "issue.created", JSON.stringify(payload));
358	    }),
359	    subscribe("issue.status_changed", async (payload) => {
360	      await enqueueForOrg(
361	        payload.orgId,
362	        "issue.status_changed",
363	        JSON.stringify(payload),
364	      );
365	    }),
366	    subscribe("comment.created", async (payload) => {
367	      await enqueueForOrg(
368	        payload.orgId,
369	        "comment.created",
370	        JSON.stringify(payload),
371	      );
372	    }),
373	    subscribe("billing.plan_changed", async (payload) => {
374	      await enqueueForOrg(
375	        payload.orgId,
376	        "billing.plan_changed",
377	        JSON.stringify(payload),
378	      );
379	    }),
380	  ];
381	
382	  return () => {
383	    for (const off of offs) off();
384	  };
