491	/**
492	 * The one place a quota is evaluated. Every guard elsewhere calls this rather
493	 * than reading `PLAN_LIMITS` itself, so a new plan dimension needs changing in
494	 * exactly two files: `plan-limits.ts` and `usageFor()` below.
495	 */
496	export async function checkLimit(
497	  orgId: OrgId,
498	  resource: LimitedResource,
499	  requested = 1,
500	): Promise<LimitCheck> {
501	  const plan = await planFor(orgId);
502	  const used = await usageFor(orgId, resource);
503	  const limit = getLimit(plan, resource);
504	
505	  return {
506	    resource,
507	    plan,
508	    limit,
509	    used,
510	    remaining: Math.max(0, limit - used),
511	    exceeded: wouldExceedLimit(plan, resource, used, requested),
512	  };
513	}
