515	/** Throwing form used by the create paths, and it emits the breach event. */
516	export async function assertWithinLimit(
517	  orgId: OrgId,
518	  resource: LimitedResource,
519	  requested = 1,
520	): Promise<void> {
521	  const check = await checkLimit(orgId, resource, requested);
522	  if (!check.exceeded) return;
523	
524	  await emit("billing.limit_exceeded", {
525	    orgId,
526	    actorId: null,
527	    occurredAt: toIsoTimestamp(new Date()),
528	    resource,
529	    limit: check.limit,
530	    used: check.used,
531	  });
532	
533	  throw new Error(
534	    `Plan ${check.plan} allows ${check.limit} ${resource}; ${check.used} are in use`,
535	  );
536	}
