682	/** Token bucket protecting the invite mailer from being used as a spam relay. */
683	const INVITE_BUCKET = "member:invite";
684	
685	/** Default validity of a freshly minted invitation, in days. */
686	const DEFAULT_EXPIRY_DAYS = 14;
