701	/**
702	 * Bulk invite. The seat quota is checked once for the whole batch — inviting
703	 * five people into a plan with three free seats must fail as a batch rather
704	 * than half-succeeding — and the rate limit is charged per invite.
705	 */
706	export async function inviteMembers(
707	  actor: Actor,
708	  input: InviteMembersInput,
709	): Promise<readonly Invitation[]> {
710	  assertOrgScope(actor, input.orgId);
711	  assertCan(actor, "member:invite", orgResource(input.orgId));
712	
713	  const verdict = await consumeRateLimit(
714	    input.orgId,
715	    INVITE_BUCKET,
716	    input.invites.length,
717	  );
718	  if (!verdict.allowed) {
719	    throw new Error(
720	      `Invite rate limit reached; try again after ${verdict.resetAt}`,
721	    );
722	  }
723	
724	  const org = requireFound(
725	    await orgRepo.findOrgById(input.orgId),
726	    "Organization",
727	    input.orgId,
728	  );
729	
730	  const seatsUsed =
731	    (await memberRepo.countActiveMembers(input.orgId)) +
732	    (await invitationRepo.countPendingInvitations(input.orgId));
733	
734	  if (
735	    wouldExceedLimit(org.plan, "seats", seatsUsed, input.invites.length)
736	  ) {
737	    const limits = getPlanLimits(org.plan);
738	    throw new Error(
739	      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
740	    );
741	  }
742	
743	  const invitations: Invitation[] = [];
744	
745	  for (const invite of input.invites) {
746	    const token = randomToken(32);
747	    const invitation = await invitationRepo.insertInvitation(
748	      input.orgId,
749	      {
750	        orgId: input.orgId,
751	        email: invite.email,
752	        role: invite.role,
753	        expiresInDays: DEFAULT_EXPIRY_DAYS,
754	      },
755	      actor.userId,
756	      hashToken(token),
757	    );
758	
759	    invitations.push(invitation);
760	
761	    await emit("member.invited", {
762	      orgId: input.orgId,
763	      actorId: actor.userId,
764	      occurredAt: invitation.createdAt,
765	      email: invite.email,
766	      role: invite.role,
767	    });
768	  }
769	
770	  return invitations;
771	}
