773	/**
774	 * Accepting runs unauthenticated: the token is the credential, so there is no
775	 * `Actor` to scope against and every check has to come off the stored row.
776	 */
777	export async function acceptInvitation(
778	  userId: UserId,
779	  input: AcceptInvitationTokenInput,
780	): Promise<Member> {
781	  const invitation = requireFound(
782	    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
783	    "Invitation",
784	    "token",
785	  );
786	
787	  if (invitation.revokedAt !== null) {
788	    throw new Error("That invitation has been revoked");
789	  }
790	  if (invitation.acceptedAt !== null) {
791	    throw new Error("That invitation has already been accepted");
792	  }
793	  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
794	    throw new Error("That invitation has expired");
795	  }
796	
797	  const existing = await memberRepo.findMember(invitation.orgId, userId);
798	  if (existing) return existing;
799	
800	  const member = await memberRepo.insertMember(
801	    invitation.orgId,
802	    userId,
803	    invitation.role,
804	    invitation.invitedBy,
805	  );
806	
807	  await invitationRepo.markInvitationAccepted(
808	    invitation.orgId,
809	    invitation.id,
810	    toIsoTimestamp(new Date()),
811	  );
812	
813	  await emit("member.joined", {
814	    ...envelope(invitation.orgId, userId),
815	    memberId: member.id,
816	    userId,
817	    role: member.role,
818	  });
819	
820	  return member;
821	}
