  void request;

  try {
    const principal = await getSessionPrincipal();
    if (principal === null) {
      return failure("unauthorized", "No active session.");
    }

    return Response.json({
      userId: principal.userId,
      email: principal.email,
      activeOrgId: principal.activeOrgId,
      expiresAt: principal.expiresAt,
    });
  } catch (error) {
    return errorResponse(error);
  }
}
/**
 * Receives third-party callbacks validated with `inboundWebhookSchema`.
 *
 * Owner D. The receiver is deliberately dumb: it validates the envelope, charges
 * a rate limit and hands the payload to the event bus. Anything that needs to
 * happen as a result is a subscriber's job, so a slow handler cannot make the
 * sender time out and retry.
 *
 * Must call (do not reimplement): inboundWebhookSchema, consumeRateLimit
 */

import { ANONYMOUS_ORG_ID } from "@/actions/_lib/permission-resources";
import { errorResponse, failure } from "@/app/api/_lib/responses";
import { emit } from "@/lib/event-bus";
import { consumeRateLimit } from "@/lib/rate-limit";
import { inboundWebhookSchema } from "@/schemas/webhook";
import { toIsoTimestamp } from "@/types/common";

export const dynamic = "force-dynamic";

const INBOUND_BUCKET = "webhook:inbound";

export async function POST(request: Request): Promise<Response> {
  try {
    // The sender is not a tenant, so the bucket is the shared anonymous one.
    const verdict = await consumeRateLimit(ANONYMOUS_ORG_ID, INBOUND_BUCKET);
    if (!verdict.allowed) {
      return failure("rate_limited", "Too many inbound callbacks.");
    }

    const body: unknown = await request.json();
    const parsed = inboundWebhookSchema.safeParse(body);
    if (!parsed.success) {
      return failure("validation_failed", "Unrecognised callback envelope.");
    }

    await emit("webhook.delivery_requested", {
      orgId: ANONYMOUS_ORG_ID,
      actorId: null,
      occurredAt: toIsoTimestamp(parsed.data.occurredAt),
      eventType: `inbound.${parsed.data.source}`,
      payload: parsed.data.payload,
    });

    // 202: the callback is accepted, not yet acted on.
    return Response.json({ accepted: true, eventId: parsed.data.eventId }, { status: 202 });
  } catch (error) {
    return errorResponse(error);
  }
}
/**
 * Cron-style trigger for the digest job.
 *
 * Owner D. The route is a trigger, not the job: `runDigestEmailJob` decides
 * which organizations are due based on their `digestHourUtc`, so calling this
 * every hour is correct and calling it twice in one hour is harmless.
 *
 * Must call (do not reimplement): runDigestEmailJob
 */

import { assertCronSecret, errorResponse } from "@/app/api/_lib/responses";
import { runDigestEmailJob } from "@/server/jobs/digest-email-job";

export const dynamic = "force-dynamic";

export async function POST(request: Request): Promise<Response> {
  try {
    assertCronSecret(request);

    const result = await runDigestEmailJob(new Date());
    return Response.json(result);
  } catch (error) {
    return errorResponse(error);
  }
}
/**
 * Current usage and limit checks for one organization.
 *
 * Owner D. Returns the raw counters *and* the plan ceilings side by side, so a
 * dashboard can render a meter without knowing the plan table itself.
 *
 * Must call (do not reimplement): can, assertOrgScope, getPlanLimits
 */

import { errorResponse, failure } from "@/app/api/_lib/responses";
import { getPlanLimits } from "@/config/plan-limits";
import { requireActorFor } from "@/lib/actor";
import { can } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { orgIdSchema } from "@/schemas/common";
import { checkLimit } from "@/server/services/billing-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import { getUsage } from "@/server/services/usage-service";
import type { LimitedResource } from "@/types/billing";

export const dynamic = "force-dynamic";

type RouteContext = { params: Promise<{ orgId: string }> };

const REPORTED: readonly LimitedResource[] = [
  "seats",
  "projects",
  "storageMb",
  "webhooks",
];

export async function GET(
  request: Request,
  context: RouteContext,
): Promise<Response> {
  void request;

  try {
    // Next.js 16: route `params` is a Promise and MUST be awaited.
    const { orgId } = await context.params;
    const parsed = orgIdSchema.safeParse(orgId);
    if (!parsed.success) {
      return failure("validation_failed", "Malformed organization id.");
    }

    const actor = await requireActorFor(parsed.data);
    assertOrgScope(actor, parsed.data);

    if (!can(actor, "org:read", { kind: "organization", orgId: parsed.data })) {
      return failure("forbidden", "You cannot read this organization.");
    }

    const [{ organization }, usage] = await Promise.all([
      getOrganizationSummary(actor, parsed.data),
      getUsage(actor, parsed.data),
    ]);

    const limits = getPlanLimits(organization.plan);
    const checks = await Promise.all(
      REPORTED.map((resource) => checkLimit(parsed.data, resource, 0)),
    );

    return Response.json({ plan: organization.plan, limits, usage, checks });
  } catch (error) {
    return errorResponse(error);
  }
}
"use server";

/**
 * Signs a user in and sets the session cookie.
 *
 * Owner D. Runs before any tenant is known, so it cannot go through
 * `withAction()` — there is no `Actor` to resolve yet. The rate limit is
 * charged against the anonymous bucket to blunt credential stuffing.
 *
 * Must call (do not reimplement): loginSchema, setSessionCookie,
 * consumeRateLimit
 */

import { ANONYMOUS_ORG_ID } from "@/actions/_lib/permission-resources";
import { RateLimitedError } from "@/actions/_lib/action-errors";
import { toActionResult } from "@/lib/errors";
import { consumeRateLimit } from "@/lib/rate-limit";
import { setSessionCookie } from "@/lib/session";
import { loginSchema } from "@/schemas/auth";
import { login } from "@/server/services/auth-service";
import { resolveSession } from "@/server/services/session-service";
import { UnauthorizedActionError } from "@/actions/_lib/action-errors";
import type { ActionResult } from "@/types/api";
import type { SessionPrincipal } from "@/types/member";

const LOGIN_BUCKET = "auth:login";

export async function loginAction(raw: unknown): Promise<ActionResult<SessionPrincipal>> {
  const parsed = loginSchema.safeParse(raw);
  if (!parsed.success) {
    return toActionResult(parsed.error);
  }

  try {
    const verdict = await consumeRateLimit(ANONYMOUS_ORG_ID, LOGIN_BUCKET);
    if (!verdict.allowed) {
      throw new RateLimitedError(LOGIN_BUCKET, verdict.resetAt);
    }

    const { token } = await login(parsed.data);
    const principal = await resolveSession(token);
    if (principal === null) {
      throw new UnauthorizedActionError("That sign-in could not be completed.");
    }

    await setSessionCookie(token, principal.expiresAt);
    return { ok: true, data: principal, submittedAt: new Date().toISOString() };
  } catch (error) {
    return toActionResult(error);
  }
}
"use server";

/**
 * Creates a user, their first organization and the owner membership.
 *
 * Owner D. `AuthService.register` performs all three writes in one transaction;
 * this action only turns the result into a session.
 *
 * Must call (do not reimplement): registerSchema, setSessionCookie
 */

import { toActionResult } from "@/lib/errors";
import { setSessionCookie } from "@/lib/session";
import { registerSchema } from "@/schemas/auth";
import { register } from "@/server/services/auth-service";
import { createSessionToken } from "@/server/services/session-service";
import type { ActionResult } from "@/types/api";
import type { SessionPrincipal } from "@/types/member";

export async function registerAction(raw: unknown): Promise<ActionResult<SessionPrincipal>> {
  const parsed = registerSchema.safeParse(raw);
  if (!parsed.success) {
    return toActionResult(parsed.error);
  }

  try {
    const { user, org } = await register(parsed.data);
    const { token, expiresAt } = await createSessionToken(user.id);
    await setSessionCookie(token, expiresAt);

    const principal: SessionPrincipal = {
      userId: user.id,
      email: user.email,
      activeOrgId: org.id,
      expiresAt,
    };
    return { ok: true, data: principal, submittedAt: new Date().toISOString() };
  } catch (error) {
    return toActionResult(error);
  }
}

