export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(and(eq(members.userId, userId), isNull(members.archivedAt)))
    .all();
''','''/**
 * True when the workspace exists and has been closed. A missing row is *not*
 * closed — callers that care about existence check it separately — so this is
 * safe to ask about sentinel ids such as the anonymous org.
 */
export async function isOrgClosed(orgId: OrgId): Promise<boolean> {
  const row = getDb()
    .select({ archivedAt: organizations.archivedAt })
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row !== undefined && row.archivedAt !== null;
}

/**
 * Every open org the user still holds a live membership in. A closed
 * workspace is gone for everyone, so it never appears in a switcher.
 */
export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(
      and(
        eq(members.userId, userId),
        isNull(members.archivedAt),
        isNull(organizations.archivedAt),
      ),
    )
    .all();
