  const row = getDb()
    .update(organizations)
    .set(archivePatch())
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}''','''/**
 * Closes the workspace. Closing is final, so the update only matches a row
 * that is still open: a second close is a conflict rather than a fresh
 * `archivedAt` stamp, even when two requests race.
