import { getDb, webhookDeliveries, subscriptions } from "@/server/db";
import { eq } from "drizzle-orm";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
import type { Tenant } from "./server/_support/fixtures";
import type { IsoTimestamp } from "@/types/common";

let cleanup: () => void;
let a: Tenant;
let b: Tenant;
const NOW = new Date("2026-06-01T07:00:00.000Z");

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
  a = await createTenant("closing");
  b = await createTenant("staying");
  await usageRepo.recomputeUsage(a.org.id);
  await usageRepo.recomputeUsage(b.org.id);
});
afterAll(() => cleanup());

describe("closed workspace", () => {
  it("end to end", async () => {
    const principal = (userId: Tenant["userIds"]["owner"]) => ({
      userId, email: "x@y.z", activeOrgId: a.org.id, expiresAt: "2099-01-01T00:00:00.000Z" as IsoTimestamp,
    });
    // shared member: a's member also joins b
    await memberRepo.insertMember(b.org.id, a.userIds.member, "member", null);

    for (const t of [a, b]) {
      await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, {
        title: "late", assigneeId: t.userIds.admin, dueAt: "2026-01-01T00:00:00.000Z",
      }));
      const ep = await webhookRepo.insertEndpoint({ orgId: t.org.id, url: "https://x.test/h", eventTypes: ["issue.created", "billing.plan_changed"] } as never, "secret");
      await webhookRepo.enqueueDelivery(t.org.id, ep.id, "issue.created", "{}");
      await invitationRepo.insertInvitation(t.org.id, { orgId: t.org.id, email: `inv@${t.org.slug}.test`, role: "member", expiresInDays: 14 }, t.userIds.owner, hashToken(`tok-${t.org.slug}`));
      getDb().update(subscriptions).set({ status: "trialing", currentPeriodEnd: "2026-05-01T00:00:00.000Z" }).where(eq(subscriptions.orgId, t.org.id)).run();
    }
    // keep seats under free for trial downgrade to apply: skip, growth has 4 seats > free 3 -> failed. fine.

    // wrong confirmation
    await expect(orgService.deleteOrganization(a.actors.owner, { orgId: a.org.id, confirmSlug: "nope" })).rejects.toThrow(/confirmation/);
    expect((await orgRepo.findOrgById(a.org.id))?.archivedAt).toBeNull();

    const closed = await orgService.deleteOrganization(a.actors.owner, { orgId: a.org.id, confirmSlug: a.org.slug });
    expect(closed.archivedAt).not.toBeNull();

    const again = await orgService.deleteOrganization(a.actors.owner, { orgId: a.org.id, confirmSlug: a.org.slug }).catch((e) => e);
    expect(again).toBeInstanceOf(AlreadyArchivedError);
    expect(toAppError(again).code).toBe("conflict");

    expect((await subscriptionRepo.findSubscription(a.org.id))?.status).toBe("canceled");
    expect((await subscriptionRepo.findSubscription(b.org.id))?.status).toBe("trialing");

    expect((await orgService.listOrganizationsForUser(a.userIds.member)).map((o) => o.id)).toEqual([b.org.id]);
    expect(await sessionService.resolveActorForOrg(principal(a.userIds.member), a.org.slug)).toBeNull();
    expect(await sessionService.resolveActorForOrg(principal(a.userIds.member), b.org.slug)).not.toBeNull();
    await expect(sessionService.switchActiveOrg(principal(a.userIds.member), { orgId: a.org.id })).rejects.toThrow();
    await sessionService.switchActiveOrg(principal(a.userIds.member), { orgId: b.org.id });
    expect(await orgService.resolveOrgBySlug(a.org.slug)).toBeNull();
    await expect(issueService.listIssues(a.actors.member, { orgId: a.org.id, limit: 10, cursor: null } as never)).rejects.toThrow();

    const joiner = await userRepo.insertUser({ email: "joiner@x.test", name: "joiner", passwordHash: "seed" });
    await expect(invitationService.acceptInvitation(joiner.id, { token: `tok-${a.org.slug}` })).rejects.toThrow();
    expect(await memberRepo.findMember(a.org.id, joiner.id)).toBeNull();
    await invitationService.acceptInvitation(joiner.id, { token: `tok-${b.org.slug}` });

    const seen: string[] = [];
    subscribe("issue.overdue", (p) => { seen.push(p.orgId); });
    subscribe("billing.plan_changed", (p) => { seen.push(`plan:${p.orgId}`); });
    await runOverdueIssueJob(NOW);
    expect(seen).toEqual([b.org.id]);

    const notesA = await notificationRepo.listNotifications({ orgId: a.org.id, recipientId: a.userIds.admin, limit: 50, cursor: null } as never);
    const notesB = await notificationRepo.listNotifications({ orgId: b.org.id, recipientId: b.userIds.admin, limit: 50, cursor: null } as never);
    expect(notesA.items.filter((n) => n.kind === "issue_overdue")).toHaveLength(0);
    expect(notesB.items.filter((n) => n.kind === "issue_overdue")).toHaveLength(1);
    const ownerNotes = await notificationRepo.listNotifications({ orgId: a.org.id, recipientId: a.userIds.owner, limit: 50, cursor: null } as never);
    expect(ownerNotes.items.filter((n) => n.kind === "member_joined")).toHaveLength(0);

    const wh = await runWebhookDeliveryJob(NOW);
    const rows = getDb().select().from(webhookDeliveries).all();
    expect(rows.filter((r) => r.orgId === a.org.id).every((r) => r.status !== "delivered" && r.deliveredAt === null)).toBe(true);
    expect(rows.filter((r) => r.orgId === b.org.id).every((r) => r.status === "delivered")).toBe(true);
    console.log("webhook", wh.processed, wh.failed);

    const trial = await runTrialExpiryJob(NOW);
    console.log("trial", trial.processed, trial.failed, seen);
    expect(seen).not.toContain(`plan:${a.org.id}`);
    const act = await activityRepo.listActivity({ orgId: a.org.id, limit: 100, cursor: null } as never);
    expect(act.items.filter((e) => e.action === "billing.plan_changed")).toHaveLength(0);

    expect((await runSearchReindexJob(a.org.id)).processed).toBe(0);
    expect((await runSearchReindexJob(b.org.id)).processed).toBeGreaterThan(0);
    await runDigestEmailJob(NOW); await runUsageRollupJob(NOW); await runCleanupArchivedJob(NOW);

    const reborn = await orgService.createOrganization(joiner.id, { name: "Again", slug: a.org.slug, plan: "free" });
    expect(reborn.slug).not.toBe(a.org.slug);
    console.log("slug", reborn.slug);
  });
});
